import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong(), m = (int) nextLong();
        // Adjacency lists in arrays: head[u] -> edge, next[edge] -> edge.
        int[] head = new int[n + 1], next = new int[2 * m], to = new int[2 * m];
        long[] weight = new long[2 * m];
        Arrays.fill(head, -1);
        for (int i = 0; i < m; i++) {
            int u = (int) nextLong(), v = (int) nextLong();
            long w = nextLong();
            to[2 * i] = v;
            weight[2 * i] = w;
            next[2 * i] = head[u];
            head[u] = 2 * i;
            to[2 * i + 1] = u;
            weight[2 * i + 1] = w;
            next[2 * i + 1] = head[v];
            head[v] = 2 * i + 1;
        }
        int source = (int) nextLong(), destination = (int) nextLong();
        if (source == destination) {
            System.out.println(0);
            return;
        }
        // Dijkstra where a path costs its largest edge: extending by w gives max(stress, w).
        long[] best = new long[n + 1];
        Arrays.fill(best, Long.MAX_VALUE);
        best[source] = 0;
        PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        heap.add(new long[] {0, source});
        while (!heap.isEmpty()) {
            long[] top = heap.poll();
            long stress = top[0];
            int u = (int) top[1];
            if (stress != best[u]) continue;
            if (u == destination) {
                System.out.println(stress);
                return;
            }
            for (int e = head[u]; e != -1; e = next[e]) {
                long candidate = Math.max(stress, weight[e]);
                if (candidate < best[to[e]]) {
                    best[to[e]] = candidate;
                    heap.add(new long[] {candidate, to[e]});
                }
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"math"
	"os"
)

type item struct {
	stress int64
	node   int
}

type pq []item

func (h pq) Len() int           { return len(h) }
func (h pq) Less(i, j int) bool { return h[i].stress < h[j].stress }
func (h pq) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *pq) Push(x any)        { *h = append(*h, x.(item)) }
func (h *pq) Pop() any {
	old := *h
	v := old[len(old)-1]
	*h = old[:len(old)-1]
	return v
}

type edge struct {
	to int
	w  int64
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(in, &n, &m)
	graph := make([][]edge, n+1)
	for i := 0; i < m; i++ {
		var u, v int
		var w int64
		fmt.Fscan(in, &u, &v, &w)
		graph[u] = append(graph[u], edge{v, w})
		graph[v] = append(graph[v], edge{u, w})
	}
	var source, destination int
	fmt.Fscan(in, &source, &destination)
	if source == destination {
		fmt.Println(0)
		return
	}
	// Dijkstra where a path costs its largest edge: extending by w gives max(stress, w).
	best := make([]int64, n+1)
	for i := range best {
		best[i] = math.MaxInt64
	}
	best[source] = 0
	h := &pq{{0, source}}
	for h.Len() > 0 {
		top := heap.Pop(h).(item)
		if top.stress != best[top.node] {
			continue
		}
		if top.node == destination {
			fmt.Println(top.stress)
			return
		}
		for _, e := range graph[top.node] {
			candidate := max(top.stress, e.w)
			if candidate < best[e.to] {
				best[e.to] = candidate
				heap.Push(h, item{candidate, e.to})
			}
		}
	}
	fmt.Println(-1)
}
